import {occasionFamilies} from './cover-catalog.js';
import {samplePhotos} from './sample-photos.js';
import {occasions} from './occasions.js';
import {cleanExperience} from './experience.js';
import {cleanAppearance,appearancePalette} from './appearance.js';
import {cleanStationery} from './stationery.js';
export function modelExample(model){const photoNames={memorias:'family',historia:'life-friends','album-casal':'couple',natal:'life-natal',maes:'life-mother',pais:'life-father',aniversario:'life-birthday',saudade:'young-couple-city','convite-casamento':'life-wedding','convite-festa':'friends',formatura:'life-graduation',pascoa:'life-easter'},photo='assets/photo-'+(photoNames[model.id]||'life-pet')+'.webp',[firstSample,secondSample]=samplePhotos(model.occasion),second=secondSample===photo?firstSample:secondSample,occasion=occasions[model.occasion],appearance=cleanAppearance(model.appearance);return {...model,coverArt:occasionFamilies[model.occasion]||'familia',openingStyle:occasionFamilies[model.occasion]||'familia',isExample:true,recipient:({memorias:'Nossa família',historia:'Júlia & Bia',saudade:'Meu amor',maes:'Mãe',pais:'Pai','album-casal':'Lia & Rafa','convite-casamento':'Lia & Rafa','convite-festa':'Ju','formatura':'Juliana',natal:'Nossa família'})[model.id]||'Alguém especial',photo,photos:[{id:'example-1',src:photo,name:'Uma lembrança',caption:'A gente, do nosso jeito.'},{id:'example-2',src:second,name:'Um outro capítulo',caption:'Tem carinho aqui dentro.'}],theme:model.character==='people'?{sheet:'people',row:Math.floor((model.person||0)/4),col:(model.person||0)%4,label:occasion.label}:occasion,appearance,color:appearancePalette(appearance).accent,texture:'algodao',pattern:'signature-'+(model.occasion==='casamento'?3:model.occasion==='aniversario'?2:0),stationeryDesign:cleanStationery({layout:model.layout,title:model.coverTitle}),experience:cleanExperience({sender:'Rafa',sound:'off',reply:false}),eventDate:model.format==='convite'?'2026-12-20':'',eventPlace:model.format==='convite'?'Casa do Jardim':'',pages:[{title:'O nosso primeiro capítulo',message:model.message,photo},{title:'Tantas histórias para guardar',message:'Este é um exemplo. O seu presente vai ter as suas fotos e as suas palavras.',photo:second}]};}
